import{z as o,x as i,o as e,c as m,q as A,j as l,D as E,d as r,s as n,S as s,b as B}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"索引工程：HNSW 参数学","description":"","frontmatter":{"title":"索引工程：HNSW 参数学","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rag-index-hnsw-params.md","filePath":"llm/rag-index-hnsw-params.md","lastUpdated":1791063341000}'),h={name:"llm/rag-index-hnsw-params.md"};function d(p,a,c,f,C,D){const t=i("Mermaid");return e(),m("div",null,[a[2]||(a[2]=A('<h1 id="索引工程-hnsw-参数学" tabindex="-1">索引工程：HNSW 参数学 <a class="header-anchor" href="#索引工程-hnsw-参数学" aria-label="Permalink to &quot;索引工程：HNSW 参数学&quot;">​</a></h1><div class="epigraph"><p>建索引的超参买图的质量，查询的超参买当次的延迟；两本账混着记，召回掉了不知道该找谁。</p><footer>—— Malkov 与 Yashunin 的 HNSW 论文；据 ANN 调参工程实践整理</footer></div><p><a href="/llm/rag-embedding-selection">上一课</a>钉住了向量空间：选型走自建验证集，微调走双评测。空间就绪，本课把它变成能扛住千万级库与延迟预算的索引。HNSW 的结构与图直觉在主干<a href="/llm/hnsw-ivf">HNSW / IVF</a>课：多层图、贪心搜索、近似换延迟。本课只写工程要回答的三件事：参数各管什么、内存怎么算、召回–延迟曲线怎么在自己的分布上画出来并存档。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>HNSW 的参数分两套预算。建索引侧：\\(M\\) 是每个节点保留的邻居数（第 0 层约 \\(2M\\)），\\(M\\) 太小则图稀疏甚至局部不连通，召回上限被锁死，之后调任何查询参数都补不回来；\\(\\mathrm{efConstruction}\\) 是建图时的候选队列宽度，决定边选得好不好。查询侧：\\(\\mathrm{efSearch}\\) 是搜索时的候选队列宽度，是每次查询现付的延迟。两套混淆的典型病症：召回不达标就无限加大 \\(\\mathrm{efSearch}\\)——延迟翻倍而召回纹丝不动，因为瓶颈在图质量；或者反过来，用默认 \\(M\\) 上线，靠加大 \\(\\mathrm{efSearch}\\) 硬撑，尾延迟随流量崩。</p><p><span class="marginnote">直觉类比：\\(M\\) 和 \\(\\mathrm{efConstruction}\\) 像城市路网的密度——路修得稀，再聪明的导航也绕不到某些街区；\\(\\mathrm{efSearch}\\) 像导航每次展开多少条备选路线——路网好时多看几条只是多花一点时间，路网本身断连时看再多备选也到不了目的地。修路是建设期决策（建索引），导航是每次出行的开销（查询）。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先算内存。每向量占 \\(4d\\) 字节浮点，加邻接表约 \\(2M\\) 条边（第 0 层）乘每条几字节的邻居编号；以 \\(d=768\\)、\\(M=32\\) 计，向量约 3 KB、边约 0.3 KB，一千万向量约 35 GB 上下。降内存三路：降维（上一课的 Matryoshka 截断）、量化（<a href="/llm/pq-vector-index">乘积量化</a>与标量量化）、减 \\(M\\)——三者的召回代价都要单独测。</p><p>再画曲线。固定 \\(k\\) 与查询分布，从 \\(k\\) 起扫 \\(\\mathrm{efSearch}\\)（经验上 \\(2k\\) 到 \\(10k\\) 之间找拐点），记录 Recall@\\(k\\) 对 QPS 与 p99；然后回到建索引侧，加 \\(M\\) 或 \\(\\mathrm{efConstruction}\\)，看整条曲线是否上移——上移才是买到了图质量，曲线不动则查询侧已饱和。把曲线（不是单点）连同 \\(M\\)、\\(\\mathrm{efConstruction}\\)、嵌入版本写进索引卡，随索引一起版本化。</p><p>最后过一遍过滤：带权限的查询先过滤后搜索会把图上指向已过滤节点的边打断，遍历困在远处局部极小，召回骤降；边搜边滤则要确认候选预算不被过滤耗尽。过滤与遍历的交互属于正确性而非性能，主干<a href="/llm/hnsw-ivf">HNSW / IVF</a>课已有此口径，这里要补的是：过滤查询的召回曲线要按「过滤后保留集」单独画，与全库曲线不是一条。</p>',10)),(e(),l(s,null,{default:E(()=>[n(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20MEM%5B%22%E5%86%85%E5%AD%98%E8%B4%A6%EF%BC%9A%E5%90%91%E9%87%8F%20%2B%20%E9%82%BB%E6%8E%A5%E8%A1%A8%22%5D%20--%3E%20CUT%5B%22%E9%99%8D%E7%BB%B4%20%2F%20%E9%87%8F%E5%8C%96%20%2F%20%E5%87%8F%20M%22%5D%0A%20%20CUT%20--%3E%20BUILD%5B%22%E5%AE%9A%20M%20%E4%B8%8E%20efConstruction%22%5D%0A%20%20BUILD%20--%3E%20SWEEP%5B%22%E5%9B%BA%E5%AE%9A%E9%A2%84%E7%AE%97%E6%89%AB%20efSearch%22%5D%0A%20%20SWEEP%20--%3E%20CURVE%5B%22Recall%E2%80%93QPS%20%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20CURVE%20--%3E%20SAT%7B%22%E6%9B%B2%E7%BA%BF%E9%A5%B1%E5%92%8C%EF%BC%9F%22%7D%0A%20%20SAT%20--%3E%7C%E6%98%AF%7C%20CARD%5B%22%E5%86%99%E7%B4%A2%E5%BC%95%E5%8D%A1%E5%B9%B6%E7%89%88%E6%9C%AC%E5%8C%96%22%5D%0A%20%20SAT%20--%3E%7C%E5%90%A6%EF%BC%8C%E4%B8%8A%E9%99%90%E4%BD%8E%7C%20BUILD%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B("h2",{id:"机制",tabindex:"-1"},[r("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=B("p",null,"为什么 \\(\\mathrm{efSearch}\\) 有饱和点：贪心搜索的候选宽度超过图质量上限后，多扫只是重复访问同一片邻域，额外延迟买不到召回；图质量由 \\(M\\) 与 \\(\\mathrm{efConstruction}\\) 一次性买断。为什么过滤如此危险：HNSW 假设全库连通，过滤后的保留集在图上可能只剩稀疏散点，遍历要么提前断路、要么绕远——工程上要么放大 \\(\\mathrm{efSearch}\\) 补偿，要么换支持过滤感知遍历的实现。为什么难查询先崩：平均召回掩盖切片，近邻密集且易混的查询上，近似的丢真近邻概率远高于均值，曲线必须按查询切片重画。",-1)),(e(),l(s,null,{default:E(()=>[n(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20FQ%5B%22%E5%B8%A6%E6%9D%83%E9%99%90%E8%BF%87%E6%BB%A4%E7%9A%84%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20PRE%7B%22%E8%BF%87%E6%BB%A4%E6%97%B6%E6%9C%BA%EF%BC%9F%22%7D%0A%20%20PRE%20--%20%22%E5%85%88%E8%BF%87%E6%BB%A4%E5%90%8E%E6%90%9C%E7%B4%A2%22%20--%3E%20BROKEN%5B%22%E5%9B%BE%E4%B8%8A%E8%BE%B9%E6%8C%87%E5%90%91%E8%A2%AB%E6%BB%A4%E6%8E%89%E7%9A%84%E8%8A%82%E7%82%B9%22%5D%0A%20%20BROKEN%20--%3E%20TRAP%5B%22%E9%81%8D%E5%8E%86%E6%8F%90%E5%89%8D%E6%96%AD%E8%B7%AF%E6%88%96%E5%9B%B0%E5%9C%A8%E8%BF%9C%E5%A4%84%22%5D%0A%20%20TRAP%20--%3E%20DROP%5B%22%E5%8F%AC%E5%9B%9E%E9%AA%A4%E9%99%8D%2C%20%E5%86%8D%E5%A4%A7%20efSearch%20%E4%B9%9F%E9%9A%BE%E8%A1%A5%22%5D%0A%20%20PRE%20--%20%22%E8%BE%B9%E6%90%9C%E8%BE%B9%E6%BB%A4%22%20--%3E%20BUDGET%5B%22%E5%80%99%E9%80%89%E9%A2%84%E7%AE%97%E5%8F%AF%E8%83%BD%E8%A2%AB%E8%BF%87%E6%BB%A4%E8%80%97%E5%B0%BD%22%5D%0A%20%20BUDGET%20--%3E%20COMP%7B%22%E9%A2%84%E7%AE%97%E5%A4%9F%E5%90%97%EF%BC%9F%22%7D%0A%20%20COMP%20--%20%22%E5%90%A6%22%20--%3E%20WIDEN%5B%22%E6%94%BE%E5%A4%A7%20efSearch%20%E8%A1%A5%E5%81%BF%22%5D%0A%20%20COMP%20--%20%22%E6%98%AF%22%20--%3E%20OK%5B%22%E6%8C%89%E4%BF%9D%E7%95%99%E9%9B%86%E5%8D%95%E7%8B%AC%E7%94%BB%E5%8F%AC%E5%9B%9E%E6%9B%B2%E7%BA%BF%E9%AA%8C%E6%94%B6%22%5D%0A%20%20WIDEN%20--%3E%20OK%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=A('<p><span class="marginnote">数字实例：\\(k=10\\) 时，\\(\\mathrm{efSearch}\\) 通常从 \\(2k=20\\) 扫到 \\(10k=100\\) 找拐点；若曲线在 \\(\\mathrm{efSearch}=40\\) 后 Recall@10 就卡在 0.85 不再涨，说明查询侧已饱和，剩下 0.15 只能靠加 \\(M\\) 或重训嵌入去买——继续拉高 \\(\\mathrm{efSearch}\\) 只是白付延迟。</span></p><p><span class="marginnote">\\(M\\) 常见 16–48、\\(\\mathrm{efConstruction}\\) 常见 100–500 是经验区间，不是验收标准；「\\(M=16\\) 够不够」在你自己的嵌入空间上没有二手答案——换一版嵌入，同一条曲线整体作废，必须重画。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>HNSW 支持动态插入，但边质量随插入缓慢退化，大规模更新宁可分区重建，策略在增量更新课展开。库更大、内存更紧时，IVF 加 PQ 是另一条路线，结构与取舍见主干课与 PQ 课；本课的曲线方法学不变，只是横轴换成 nprobe。ANN 调参修不了坏嵌入：空间本身塌了，图再密也搜不到，先回上一课的选型与微调。曲线画完、索引卡立住之后，第二条通道（词法）怎么并进来、两路分数怎么合，是下一课的缺口。</p><p><span class="marginnote">常见误区：初学者容易把「召回率到不了 100%」当成索引出 bug。ANN 的本质就是用一点点召回换几十倍的查询速度——HNSW 是「近似」最近邻，不是精确最近邻。工程目标是在预算内把召回压到足够高（如 95%+），并知道丢的是谁（按切片画曲线），而不是追求全对。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>建索引参数（\\(M\\)、\\(\\mathrm{efConstruction}\\)）买图质量，查询参数（\\(\\mathrm{efSearch}\\)）买当次延迟，两本账分开记。</li><li>内存账先算：浮点向量加邻接表，降维、量化、减 \\(M\\) 三路的召回代价单独测。</li><li>验收物是 Recall–QPS 曲线加索引卡，不是某个参数组合的单点数字。</li><li>过滤与遍历的交互是正确性问题；平均召回掩盖难查询切片。</li><li>换嵌入即重画曲线；ANN 不修复坏嵌入。</li><li>出处：Malkov 与 Yashunin，HNSW；Jégou 等 IVF；据 ANN 调参实践整理。</li></ul>',7))])}const u=o(h,[["render",d]]);export{F as __pageData,u as default};
